<?php
declare(strict_types=1);

date_default_timezone_set('Europe/Kyiv');
require_once __DIR__ . '/ticker-settings-lib.php';

function b2h(string $value): string { return htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$config = json_decode((string)file_get_contents(dirname(__DIR__) . '/config.json'), true, 512, JSON_THROW_ON_ERROR);
$selection = selectedTickerSet($config, trim((string)($_GET['ticker_set'] ?? '')));
$sets = $selection['sets'];
$symbols = $selection['symbols'];
$selectedSymbol = strtoupper(trim((string)($_GET['symbol'] ?? ($symbols[0] ?? ''))));
if (!in_array($selectedSymbol, $symbols, true)) $selectedSymbol = $symbols[0] ?? '';
$comparisonView = (string)($_GET['view'] ?? '') === 'comparison';
$runKey = trim((string)($_GET['run_key'] ?? ''));
$compareSymbol = strtoupper(trim((string)($_GET['compare_symbol'] ?? '')));
$compareSignal = (string)($_GET['signal_mode'] ?? 'exact');
$compareDirection = (string)($_GET['direction_mode'] ?? 'follow');
$compareExit = (string)($_GET['exit_mode'] ?? 'immediate');
$compareSort = (string)($_GET['sort'] ?? 'worst');
$compareAxis = (string)($_GET['axis'] ?? 'entry');
$compareEntryId = trim((string)($_GET['entry_id'] ?? ''));
$compareExitId = trim((string)($_GET['exit_id'] ?? ''));
$comparisonUrl = 'basic-checks-2.php?' . http_build_query([
    'view'=>'comparison', 'run_key'=>$runKey, 'compare_symbol'=>$compareSymbol,
    'signal_mode'=>$compareSignal, 'direction_mode'=>$compareDirection, 'exit_mode'=>$compareExit,
    'entry_id'=>$compareEntryId, 'exit_id'=>$compareExitId,
    'axis'=>$compareAxis === 'entry' ? 'exit' : 'entry',
]);
$comparePage = max(1, (int)($_GET['page'] ?? 1));
$navUrl = 'basic-checks-2.php?' . http_build_query(['ticker_set'=>$selection['id'],'symbol'=>$selectedSymbol]);
?>
