<style>
:root{color-scheme:dark;--bg:#0b1020;--panel:#131a2d;--muted:#8995ad;--text:#e9eefb;--line:#273149;--green:#42d6a4;--red:#ff7188;--blue:#86a8ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 15% 0%,#1b2850 0,transparent 45%),var(--bg);color:var(--text);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}.wrap{max-width:none;margin:0 auto;padding:28px 20px}h1{margin:0 0 8px;font-size:clamp(26px,4vw,38px)}h2{font-size:18px;margin:0 0 12px}.eyebrow,.muted,.small-note{color:var(--muted);font-size:13px}.view-nav{display:flex;gap:7px;flex-wrap:wrap;margin:16px 0 20px;padding:5px;border:1px solid var(--line);border-radius:12px;background:#0c1222;width:max-content;max-width:100%}.view-nav a{padding:8px 12px;border-radius:8px;color:#b7c1d5;text-decoration:none}.view-nav a:hover,.view-nav a[aria-current=page]{background:#263968;color:#fff}.panel{padding:20px;margin:14px 0;border:1px solid var(--line);border-radius:16px;background:color-mix(in srgb,var(--panel) 95%,transparent);box-shadow:0 16px 40px #0002}.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:12px;align-items:end}.field{display:grid;gap:6px;color:var(--muted);font-size:13px;font-weight:600}.field select,.field input{width:100%;min-width:0;padding:10px 11px;border:1px solid #34415e;border-radius:9px;background:#0c1222;color:var(--text);font:inherit}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}button,.button{padding:10px 14px;border:0;border-radius:9px;background:#607df4;color:white;font:inherit;font-weight:700;cursor:pointer;text-decoration:none}button.secondary,.button.secondary{background:#34415e}button.danger{background:#9c3949}button:disabled{opacity:.5;cursor:not-allowed}.status{min-height:24px;margin:12px 0;color:#b7c1d5;white-space:pre-line}.status.error{color:#ff9eaa}.progress{height:10px;overflow:hidden;border-radius:9px;background:#202b43}.progress>span{display:block;width:0;height:100%;background:linear-gradient(90deg,#607df4,#42d6a4);transition:width .25s}.summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:10px;margin:12px 0}.stat{padding:12px;border:1px solid var(--line);border-radius:10px;background:#0c1222}.stat span{display:block;color:var(--muted);font-size:12px}.stat strong{font-size:18px;font-variant-numeric:tabular-nums}.gain,.best-max{color:var(--green)}.loss,.best-min{color:var(--red)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:9px 10px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}th{color:#adb9d0;white-space:nowrap}td.numeric{font-variant-numeric:tabular-nums;white-space:nowrap}.intervals{margin-top:8px}.intervals summary{color:#b8c8ff;cursor:pointer}.intervals table{margin-top:8px}.empty{padding:24px;text-align:center;color:var(--muted)}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.badge{display:inline-block;padding:3px 7px;border-radius:99px;background:#202b43;color:#c6d2ee;font-size:12px}.hidden{display:none!important}@media(max-width:600px){.wrap{padding:18px 12px}.panel{padding:14px}.view-nav{width:100%}.view-nav a{flex:1;text-align:center}.actions>*{flex:1;text-align:center}}
</style>
