</main>
<script>
const apiUrl='basic-checks-2-data.php';
const formatNumber=value=>Number.isFinite(Number(value))?Number(value).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}):'—';
const signed=value=>`${Number(value)>0?'+':''}${formatNumber(value)}%`;
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
let renderedResultsSignature='';
function renderIntervals(rows){return `<details class="intervals"><summary>Интервалы (${rows.length})</summary><table><thead><tr><th>Период</th><th>Доходность</th><th>Итог, USDT</th><th>Капитал после интервала</th></tr></thead><tbody>${rows.map((period,index)=>`<tr class="${index===rows.reduce((best,item,i,all)=>Number(item.return_percent)<Number(all[best].return_percent)?i:best,0)?'best-min':''}"><td>${escapeHtml(period.label)}</td><td class="numeric">${signed(period.return_percent)}</td><td class="numeric">${formatNumber(period.profit_usdt)}</td><td class="numeric">${formatNumber(period.equity_end)} USDT</td></tr>`).join('')}</tbody></table></details>`;}
<?php if (!$comparisonView): ?>
const tickerSet=document.querySelector('#ticker-set'),symbolSelect=document.querySelector('#symbol'),coverageNode=document.querySelector('#coverage'),statusNode=document.querySelector('#run-status'),resultsPanel=document.querySelector('#results-panel'),resultsNode=document.querySelector('#results'),progressBar=document.querySelector('#progress-bar'),stopButton=document.querySelector('#stop-run');
let runKey=new URLSearchParams(location.search).get('run_key')||'',pollTimer=0;
async function loadCoverage(){const params=new URLSearchParams({action:'init',ticker_set:tickerSet.value});const response=await fetch(`${apiUrl}?${params}`,{cache:'no-store'});const data=await response.json();if(!response.ok||data.status==='error')throw new Error(data.message||'Не удалось проверить данные');coverageNode.textContent=`Список «${data.set_name}»: ${data.symbols.length} тикеров. Общий диапазон котировок определяется пересечением доступных данных выбранного списка.`;}
function comparisonLink(row,axis){const link=new URL('basic-checks-2.php',location.href);Object.entries({view:'comparison',axis,run_key:runKey,compare_symbol:row.symbol,signal_mode:row.signal_mode,direction_mode:row.direction_mode,exit_mode:row.exit_mode,entry_id:row.entry_id,exit_id:row.exit_id}).forEach(([key,value])=>link.searchParams.set(key,String(value??'')));return escapeHtml(link)}
function renderResults(data){const items=[...(data.results||[])].sort((a,b)=>Number(b.worst_percent)-Number(a.worst_percent)||String(a.symbol).localeCompare(String(b.symbol))||String(a.objective).localeCompare(String(b.objective)));const signature=JSON.stringify(items.map(row=>[row.symbol,row.objective,row.entry_id,row.exit_id,row.worst_percent,row.sum_percent,row.total_percent]));if(signature===renderedResultsSignature)return;renderedResultsSignature=signature;resultsPanel.classList.remove('hidden');document.querySelector('#result-caption').textContent=`${data.request?.scope==='list'?'Список':'Тикер'} · ${data.periods?.length||0} полных интервалов`;if(!items.length){resultsNode.innerHTML='<div class="empty">Нет стратегий, прошедших порог доходности.</div>';return}resultsNode.innerHTML=`<table><thead><tr><th>Тикер</th><th>Цель</th><th>Тип входа</th><th>Направление</th><th>Тип выхода</th><th>Худший интервал</th><th>Сумма интервалов*</th><th>Итог диапазона</th><th>Закрытий</th><th>Интервалы</th></tr></thead><tbody>${items.map(row=>{const objective=row.objective==='minimum_worst'?'Минимальная просадка':'Максимальная сумма';return `<tr><td>${escapeHtml(row.symbol)}</td><td>${objective}</td><td><a target="_blank" rel="noopener" href="${comparisonLink(row,'entry')}">${row.signal_mode==='within'?'Внутри окна':'Точное пересечение'} · ${escapeHtml(row.entry_label)}</a></td><td>${row.direction_mode==='reverse'?'Против сигнала':'По сигналу'}</td><td><a target="_blank" rel="noopener" href="${comparisonLink(row,'exit')}">${escapeHtml(row.exit_label)}</a></td><td class="numeric best-min">${signed(row.worst_percent)}</td><td class="numeric best-max">${signed(row.sum_percent)}</td><td class="numeric">${signed(row.total_percent)}</td><td class="numeric">${row.closed_trades}</td><td>${renderIntervals(row.periods||[])}</td></tr>`}).join('')}</tbody></table><p class="small-note">* Арифметическая сумма процентов интервалов — критерий цели «Максимальная сумма».</p>`;}
async function pollStatus(){if(!runKey)return;try{const response=await fetch(`${apiUrl}?action=status&run_key=${encodeURIComponent(runKey)}`,{cache:'no-store'});const data=await response.json();if(!response.ok||data.status==='error')throw new Error(data.message||'Ошибка статуса');const progress=Number(data.progress)||0;progressBar.style.width=`${progress}%`;const eta=Number.isFinite(Number(data.remaining_seconds))?` · осталось примерно ${Math.ceil(Number(data.remaining_seconds)/60)} мин.`:'';statusNode.textContent=`${data.message||'Расчёт выполняется'} · ${formatNumber(progress)}%${eta}`;const running=data.status==='running';stopButton.classList.toggle('hidden',!running);document.querySelector('#run-one').disabled=running;document.querySelector('#run-list').disabled=running;if(data.results?.length){runKey=data.run_key||runKey;renderResults(data)}if(data.status==='ready'){clearInterval(pollTimer);runKey=data.run_key||runKey;renderResults(data);statusNode.textContent=`Расчёт завершён · ${data.done||data.total||0} вариантов.`}else if(data.status==='error'||data.status==='cancelled'){clearInterval(pollTimer);statusNode.classList.add('error');statusNode.textContent=data.message||'Расчёт остановлен.'}}catch(error){statusNode.classList.add('error');statusNode.textContent=error.message;}}
async function startRun(scope){statusNode.classList.remove('error');statusNode.textContent='Создаю расчёт…';resultsPanel.classList.add('hidden');const body=new URLSearchParams({action:'start',ticker_set:tickerSet.value,scope,symbol:symbolSelect.value,interval:document.querySelector('#interval').value,signal_mode:document.querySelector('#signal-mode').value,direction_mode:document.querySelector('#direction-mode').value,exit_mode:document.querySelector('#exit-mode').value,balance:document.querySelector('#balance').value,fee:document.querySelector('#fee').value,include_funding:document.querySelector('#include-funding').value});try{const response=await fetch(apiUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});const data=await response.json();if(!response.ok||data.status==='error')throw new Error(data.message||'Не удалось запустить расчёт');runKey=data.run_key;const url=new URL(location.href);url.searchParams.set('ticker_set',tickerSet.value);url.searchParams.set('symbol',symbolSelect.value);url.searchParams.set('run_key',runKey);history.replaceState(null,'',url);clearInterval(pollTimer);await pollStatus();pollTimer=setInterval(pollStatus,1500)}catch(error){statusNode.classList.add('error');statusNode.textContent=error.message}}
document.querySelector('#run-one').addEventListener('click',()=>startRun('single'));document.querySelector('#run-list').addEventListener('click',()=>startRun('list'));stopButton.addEventListener('click',async()=>{if(!runKey)return;await fetch(apiUrl,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({action:'stop',run_key:runKey})});statusNode.textContent='Запрошена остановка. Сохраняю уже рассчитанные строки…'});
tickerSet.addEventListener('change',()=>{const url=new URL(location.href);url.searchParams.set('ticker_set',tickerSet.value);url.searchParams.delete('symbol');url.searchParams.delete('run_key');location.href=url});loadCoverage().catch(error=>{coverageNode.textContent=error.message});if(runKey){pollStatus();pollTimer=setInterval(pollStatus,1500)}
<?php else: ?>
let comparePage=<?= $comparePage ?>;const compareParams={action:'compare',run_key:<?= json_encode($runKey) ?>,symbol:<?= json_encode($compareSymbol) ?>,signal_mode:<?= json_encode($compareSignal) ?>,direction_mode:<?= json_encode($compareDirection) ?>,exit_mode:<?= json_encode($compareExit) ?>,sort:<?= json_encode($compareSort) ?>,axis:<?= json_encode($compareAxis) ?>,entry_id:<?= json_encode($compareEntryId) ?>,exit_id:<?= json_encode($compareExitId) ?>};
async function loadComparison(){const query=new URLSearchParams({...compareParams,page:String(comparePage)});const response=await fetch(`${apiUrl}?${query}`,{cache:'no-store'});const data=await response.json();if(!response.ok||data.status==='error'){document.querySelector('#compare-heading').textContent=data.message||'Не удалось загрузить сравнение';return}const fixed=data.axis==='entry'?`${compareParams.exit_mode} · ${compareParams.exit_id}`:`${compareParams.signal_mode} · ${compareParams.direction_mode} · ${compareParams.entry_id}`;document.querySelector('#compare-heading').textContent=`${compareParams.symbol} · ${data.axis==='entry'?'все варианты входа при фиксированном выходе':'все варианты выхода при фиксированном входе'} · ${fixed} · ${data.total} вариантов`;document.querySelector('#compare-page').textContent=`Страница ${data.page} из ${Math.max(1,Math.ceil(data.total/data.per_page))}`;document.querySelector('#compare-prev').disabled=data.page<=1;document.querySelector('#compare-next').disabled=data.page*data.per_page>=data.total;document.querySelector('#compare-results').innerHTML=data.items.length?`<table><thead><tr><th>№</th><th>Вход</th><th>Направление</th><th>Выход</th><th>Худший интервал</th><th>Сумма интервалов</th><th>Итог диапазона</th><th>Закрытий</th><th>Интервалы</th></tr></thead><tbody>${data.items.map((row,index)=>`<tr><td>${(data.page-1)*data.per_page+index+1}</td><td>${escapeHtml(row.entry_label)}</td><td>${row.signal_mode==='within'?'Внутри окна':'Точное пересечение'} · ${row.direction_mode==='reverse'?'против':'по сигналу'}</td><td>${escapeHtml(row.exit_label)}</td><td class="numeric best-min">${signed(row.worst_percent)}</td><td class="numeric best-max">${signed(row.sum_percent)}</td><td class="numeric">${signed(row.total_percent)}</td><td class="numeric">${row.closed_trades}</td><td>${renderIntervals(row.periods||[])}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Подходящих вариантов нет.</div>'}
document.querySelector('#compare-prev').addEventListener('click',()=>{comparePage=Math.max(1,comparePage-1);loadComparison()});document.querySelector('#compare-next').addEventListener('click',()=>{comparePage++;loadComparison()});loadComparison();
<?php endif; ?>
</script>
</body></html>
